-- Lot T1 des Tarides (03/11/2026) : puissance des monstres par secteur, retraits du Kraal, des Souilles et de
-- la patrouille, Aciérite déplacée, répliques des gardes. Généré par outils\puissance_tarides.py : ne pas
-- modifier à la main.
USE acore_world;

-- Secteurs (puissance conseillée de la zone : v3_niveau.cpp).
CREATE TABLE solazeroth_v3_puissance_secteurs (zone INT UNSIGNED NOT NULL, secteur TINYINT UNSIGNED NOT NULL, nom VARCHAR(64) NOT NULL, origine_min TINYINT UNSIGNED NOT NULL, origine_max TINYINT UNSIGNED NOT NULL, puissance_min TINYINT UNSIGNED NOT NULL, puissance_max TINYINT UNSIGNED NOT NULL, PRIMARY KEY (zone, secteur)) DEFAULT CHARSET=utf8mb4;
INSERT INTO solazeroth_v3_puissance_secteurs VALUES (17, 1, 'La Croisée', 10, 15, 14, 16), (17, 2, 'Les oasis et la côte', 12, 20, 18, 22), (17, 3, 'Le sud', 16, 22, 25, 27), (17, 4, 'L''extrême sud', 19, 27, 27, 30), (718, 5, 'Abords des Cavernes', 11, 17, 30, 30);
