-- Retrait : Serviteurs de Tranchebauge (surface du Kraal).
-- Retrait : surface des Souilles de Tranchebauge.
-- Retrait : patrouille de l'Alliance.
CREATE TABLE solazeroth_v3_tarides_retraits SELECT * FROM creature WHERE map = 1 AND ((areaId = 1717 AND id = 6132) OR (areaId = 1316 AND id IN (7872, 7873, 7874, 7895, 12865)) OR (id IN (5797, 5798, 5799, 5800)));
CREATE TABLE solazeroth_v3_tarides_retraits_addon SELECT * FROM creature_addon WHERE guid IN (SELECT guid FROM solazeroth_v3_tarides_retraits);
CREATE TABLE solazeroth_v3_tarides_retraits_formations SELECT * FROM creature_formations WHERE leaderGUID IN (SELECT guid FROM solazeroth_v3_tarides_retraits) OR memberGUID IN (SELECT guid FROM solazeroth_v3_tarides_retraits);
DELETE FROM creature_formations WHERE leaderGUID IN (SELECT guid FROM solazeroth_v3_tarides_retraits) OR memberGUID IN (SELECT guid FROM solazeroth_v3_tarides_retraits);
DELETE FROM creature_addon WHERE guid IN (SELECT guid FROM solazeroth_v3_tarides_retraits);
DELETE c FROM creature c JOIN solazeroth_v3_tarides_retraits r ON r.guid = c.guid;

-- Aciérite sauvage devant le Kraal : à la Crête de Noirépine.
UPDATE gameobject SET position_x = -3715.3, position_y = -1690.9, position_z = 93.6, areaId = 1701 WHERE guid = 212956;

-- Répliques des gardes des entrées scellées (v3_gouffre.cpp).
ALTER TABLE solazeroth_v3_entrees_scellees ADD COLUMN garde INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN replique VARCHAR(255) NOT NULL DEFAULT '';
UPDATE solazeroth_v3_entrees_scellees SET garde = 9100100, replique = 'Ordre de Kirge Corne-sévère : personne n''entre dans le Kraal. Les huréceros ont creusé trop profond, et ce qui vit en dessous ne nous regarde pas encore.' WHERE declencheur = 244;
UPDATE solazeroth_v3_entrees_scellees SET garde = 9100101, replique = 'Les Souilles sont mortes, et elles ne le savent pas. Personne n''y descend.' WHERE declencheur = 442;
UPDATE creature SET ScriptName = 'npc_solazeroth_v3_garde_scellee' WHERE guid IN (9100100, 9100101);
